ALTER TABLE contacts ADD COLUMN score integer NOT NULL DEFAULT 0;
ALTER TABLE contacts ADD COLUMN archived_at timestamptz;
ALTER TABLE lists ADD COLUMN description text NOT NULL DEFAULT '';
CREATE TABLE tags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, color text NOT NULL DEFAULT '#2a56d9');
CREATE TABLE contact_tags (contact_id uuid REFERENCES contacts ON DELETE CASCADE,tag_id uuid REFERENCES tags ON DELETE CASCADE,PRIMARY KEY(contact_id,tag_id));
CREATE TABLE custom_fields (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE,label text NOT NULL,type text NOT NULL CHECK(type IN ('text','number','date','boolean')));
CREATE TABLE segments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,rules jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE campaigns DROP CONSTRAINT campaigns_status_check;
ALTER TABLE campaigns ADD CONSTRAINT campaigns_status_check CHECK(status IN ('draft','scheduled','queued','paused','cancelled','completed'));
ALTER TABLE campaigns ADD COLUMN scheduled_at timestamptz;
ALTER TABLE campaigns ADD COLUMN segment_id uuid REFERENCES segments ON DELETE SET NULL;
ALTER TABLE campaigns ADD COLUMN preview_text text NOT NULL DEFAULT '';
ALTER TABLE campaigns ADD COLUMN design jsonb NOT NULL DEFAULT '{}';
ALTER TABLE campaigns ADD COLUMN tracking_enabled boolean NOT NULL DEFAULT false;
ALTER TABLE campaigns ADD COLUMN audience_ready boolean NOT NULL DEFAULT false;
ALTER TABLE messages ALTER COLUMN campaign_id DROP NOT NULL;
ALTER TABLE messages ADD COLUMN source text NOT NULL DEFAULT 'campaign' CHECK(source IN ('campaign','transactional','automation','opt_in','test'));
ALTER TABLE messages ADD COLUMN source_key text UNIQUE;
ALTER TABLE messages ADD COLUMN subject text;
ALTER TABLE messages ADD COLUMN html text;
ALTER TABLE messages ADD COLUMN variables jsonb NOT NULL DEFAULT '{}';
ALTER TABLE messages ADD COLUMN tracking_enabled boolean NOT NULL DEFAULT false;
CREATE TABLE email_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),message_id uuid NOT NULL REFERENCES messages ON DELETE CASCADE,type text NOT NULL,event_key text NOT NULL UNIQUE,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX email_events_message_idx ON email_events(message_id,type);
CREATE INDEX email_events_date_idx ON email_events(created_at);
CREATE TABLE tracking_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),message_id uuid NOT NULL REFERENCES messages ON DELETE CASCADE,url text NOT NULL,UNIQUE(message_id,url));
CREATE TABLE workspace_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id),data jsonb NOT NULL DEFAULT '{}');
INSERT INTO workspace_settings(id,data) VALUES(true,'{"name":"My workspace","company":"","postalAddress":"","timezone":"Africa/Lagos","replyTo":"","trackingEnabled":false}');
CREATE TABLE api_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,prefix text NOT NULL,key_hash text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),last_used_at timestamptz,revoked_at timestamptz);
CREATE TABLE automations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','paused')),trigger_type text NOT NULL,trigger_id uuid,steps jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE automation_enrollments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),automation_id uuid NOT NULL REFERENCES automations ON DELETE CASCADE,contact_id uuid NOT NULL REFERENCES contacts ON DELETE CASCADE,steps jsonb NOT NULL,step integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','completed','failed')),due_at timestamptz NOT NULL DEFAULT now(),error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(automation_id,contact_id));
CREATE INDEX enrollment_due_idx ON automation_enrollments(due_at) WHERE status='active';
CREATE TABLE public_forms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text NOT NULL UNIQUE,list_id uuid NOT NULL REFERENCES lists,kind text NOT NULL CHECK(kind IN ('form','page')),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')),design jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE form_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),form_id uuid NOT NULL REFERENCES public_forms ON DELETE CASCADE,contact_id uuid NOT NULL REFERENCES contacts ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours',confirmed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public_rate_limits (key text PRIMARY KEY,count integer NOT NULL DEFAULT 1,expires_at timestamptz NOT NULL);
ALTER TABLE messages ADD COLUMN automation_id uuid REFERENCES automations ON DELETE SET NULL;
ALTER TABLE automation_enrollments ADD COLUMN executions integer NOT NULL DEFAULT 0;
